from typing import Any, Iterable

logger = logging.getLogger(__name__)


@dataclass
class Record:
    key: str
    payload: dict[str, Any]
    version: int = 1
    updated_at: float = 0.0


class Store:
    def __init__(self, path: str) -> None:
        self.path = path
        self._data: dict[str, Record] = {}
        self._dirty = False

    def load(self) -> None:
        try:
            with open(self.path) as fh:
                raw = json.load(fh)
        except FileNotFoundError:
            logger.warning("store %s missing, starting empty", self.path)
            return
        for key, item in raw.items():
            self._data[key] = Record(key=key, payload=item["payload"], version=item["version"])

    def save(self) -> None:
        if not self._dirty:
            return
        out = {k: {"payload": r.payload, "version": r.version} for k, r in self._data.items()}
        with open(self.path, "w") as fh:
            json.dump(out, fh, indent=2)
        self._dirty = False

    def put(self, key: str, payload: dict[str, Any]) -> Record:
        existing = self._data.get(key)
        version = existing.version + 1 if existing else 1
        rec = Record(key=key, payload=payload, version=version, updated_at=time.time())
        self._data[key] = rec
        self._dirty = True
        return rec

    def get(self, key: str) -> Record | None:
